-- ============================================================
-- SEED EXT 5: Módulo 22 — Subjunctive (ex 169-248)
-- Novos tópicos: subjunctive em academic/legal texts avançados,
-- were...to constructions, subjunctive em TOEFL essays completos
-- ============================================================
DO $$
DECLARE cid TEXT;
BEGIN
  SELECT id INTO cid FROM contents WHERE id = 'subjunctive';
  IF cid IS NULL THEN RAISE EXCEPTION 'Módulo subjunctive não encontrado'; END IF;

  INSERT INTO exercises (content_id, block_number, exercise_number, type, question, answer, options, explanation, difficulty) VALUES

  -- BLOCK 51: Mandative subjunctive em academic/policy texts
  (cid,51,169,'gap_fill','The committee recommends that each participating country _____ (submit) an annual progress report and _____ (allow) independent verification of its compliance.','submit / allow',NULL,'Mandative subjunctive: recommend + that + subject + base verb (no -s, no auxiliary).','easy'),
  (cid,51,170,'gap_fill','It is essential that the review process _____ (be) transparent, that all stakeholders _____ (have) the opportunity to participate, and that conclusions _____ (base/passive) on the best available evidence.','be / have / be based',NULL,'Triple mandative subjunctive after "it is essential that."','hard'),
  (cid,51,171,'gap_fill','The panel insists that the findings _____ (not/release/passive) prior to peer review and that the principal investigators _____ (be) notified before any public announcement _____ (make/passive).','not be released / be notified / is made / be made',NULL,'Mandative subjunctive negative passive + multiple clauses.','hard'),
  (cid,51,172,'multiple_choice','Which mandative subjunctive is CORRECT in formal academic recommendation language?','The report urges that a comprehensive audit be conducted within six months.','["The report urges that a comprehensive audit is conducted within six months.","The report urges that a comprehensive audit be conducted within six months.","The report urges that a comprehensive audit was conducted within six months.","The report urges that a comprehensive audit will be conducted within six months."]','"Urges that + base passive" = mandative subjunctive. Not "is/was/will be."','easy'),
  (cid,51,173,'gap_fill','For the reforms _____ (succeed), it is imperative that a broad coalition _____ (build/passive) across political parties and that the implementation timeline _____ (revise/passive) to allow adequate preparation.','to succeed / be built / be revised',NULL,'"It is imperative that" + mandative subjunctive + passive forms.','hard'),

  -- BLOCK 52: Were...to constructions (formal hypothetical)
  (cid,52,174,'gap_fill','Were the proposed policy _____ (implement/passive) without adequate safeguards, the consequences for vulnerable communities _____ (be) severe and potentially irreversible.','to be implemented / would be',NULL,'"Were + subject + to + infinitive" = formal hypothetical (= Type 2 conditional with were...to).','hard'),
  (cid,52,175,'gap_fill','Were the international community _____ (agree) to a binding framework for AI governance, it _____ (represent) a significant breakthrough in managing the risks posed by advanced AI systems.','to agree / would represent',NULL,'"Were...to agree + would represent" = formal were...to hypothetical.','medium'),
  (cid,52,176,'multiple_choice','Which "were...to" sentence is MOST APPROPRIATE for an academic paper?','Were the authors to replicate this study with a larger sample, they would likely find stronger effect sizes.','["Were the authors to replicate this study with a larger sample, they will likely find stronger effect sizes.","Were the authors to replicate this study with a larger sample, they would likely find stronger effect sizes.","Were the authors replicating this study with a larger sample, they would likely find stronger effect sizes.","Were the authors will replicate this study with a larger sample, they would likely find stronger effect sizes."]','"Were + subject + to + base verb + would + base verb" = correct were...to conditional.','medium'),
  (cid,52,177,'gap_fill','Were this pattern _____ (hold) across a broader range of contexts, it _____ (challenge) several widely accepted theoretical assumptions and _____ (require) substantial revision of the prevailing model.','to hold / would challenge / would require',NULL,'"Were + subject + to hold + would + challenge/require" = hypothetical academic implication.','hard'),
  (cid,52,178,'gap_fill','Were governments _____ (fail) to act within the current decade, the opportunity for an orderly transition _____ (pass) and more costly and disruptive adaptation _____ (become) inevitable.','to fail / would pass / would become',NULL,'"Were...to fail" + double result clause with "would."','hard'),

  -- BLOCK 53: Subjunctive em textos legais formais
  (cid,53,179,'gap_fill','The agreement requires that each signatory _____ (designate) a national focal point, _____ (provide) annual implementation reports, and _____ (make) such reports publicly available.','designate / provide / make',NULL,'Triple mandative subjunctive in legal obligation clause.','medium'),
  (cid,53,180,'gap_fill','The court orders that the defendant _____ (cease and desist) all activities in violation of the injunction and _____ (appear) before the court no later than thirty days from the date of this order.','cease and desist / appear',NULL,'Court order mandative subjunctive: base verb without -s.','hard'),
  (cid,53,181,'multiple_choice','In a legal treaty, which subjunctive form is CORRECT?','The parties agree that any dispute arising under this agreement be referred to binding arbitration.','["The parties agree that any dispute arising under this agreement is referred to binding arbitration.","The parties agree that any dispute arising under this agreement be referred to binding arbitration.","The parties agree that any dispute arising under this agreement will be referred to binding arbitration.","The parties agree that any dispute arising under this agreement should be referred to binding arbitration."]','"Be referred" = mandative passive subjunctive in legal treaty language.','hard'),
  (cid,53,182,'gap_fill','It _____ (stipulate/passive) in the protocol that all data _____ (archive/passive) for a minimum period of ten years and that access _____ (restrict/passive) to authorized personnel.','is stipulated / be archived / be restricted',NULL,'Impersonal passive + mandative subjunctive passives.','hard'),
  (cid,53,183,'gap_fill','The statute provides that no person _____ (compel/passive) to testify against themselves and that all defendants _____ (presume/passive) innocent until guilt _____ (prove/passive) beyond reasonable doubt.','be compelled / be presumed / is proved / be proved',NULL,'Constitutional/legal mandative subjunctive: base passive constructions.','hard'),

  -- BLOCK 54: Subjunctive em ensaios acadêmicos (argumentação)
  (cid,54,184,'production','[TOEFL Writing — 100 words] Write a policy recommendation paragraph using mandative subjunctive throughout.','',NULL,'On the basis of the evidence reviewed, this essay proposes that governments take several coordinated steps to address the affordability crisis in housing. It is essential that national land use legislation be reformed to override restrictive local zoning that suppresses housing supply in high-demand areas. It is also imperative that public investment in social housing be substantially increased and that a proportion of proceeds from any land value uplift be captured for community benefit. The analysis further suggests that it be mandatory for all new large-scale residential developments to include a minimum proportion of below-market-rate units. Unless these measures are adopted together, it is unlikely that any single intervention will prove sufficient to restore housing affordability at the necessary scale.','hard'),
  (cid,54,185,'gap_fill','The evidence strongly suggests that it _____ (be) necessary for the international community _____ (agree) to a binding framework and that no country _____ (exempt/passive) from monitoring requirements.','is / to agree / be exempted',NULL,'"It is necessary for + subject + to agree" + "that + subject + be exempted" = mandative subjunctive.','hard'),
  (cid,54,186,'gap_fill','Were the reform agenda _____ (stall), it _____ (not/be) unreasonable _____ (expect) that political pressures for more radical alternatives _____ (intensify) considerably.','to stall / would not be / to expect / would intensify',NULL,'"Were...to stall" = hypothetical + "would not be unreasonable to expect" + "would intensify."','hard'),
  (cid,54,187,'gap_fill','Academic integrity demands that all research _____ (conduct/passive) in accordance with established ethical principles and that any conflicts of interest _____ (disclose/passive) fully and transparently.','be conducted / be disclosed',NULL,'Mandative subjunctive after "demands that" + passive forms.','medium'),

  -- BLOCK 55: TOEFL Reading avançado com subjunctive
  (cid,55,188,'multiple_choice','[TOEFL Reading] "The committee recommended that the data be re-examined by an independent panel." The word "be" in this sentence is:','The mandative subjunctive: no -s, no auxiliary, base form of "be" used for all subjects.','["Simple present passive","Future passive","The mandative subjunctive: no -s, no auxiliary, base form of ''be'' used for all subjects.","Past subjunctive"]','"Recommended that + subject + be + PP" = mandative subjunctive passive.','medium'),
  (cid,55,189,'gap_fill','[TOEFL Reading] "The treaty stipulates that all member states _____ (ratify) the protocol within two years and _____ (submit) their compliance reports annually." Best mandative forms?','ratify / submit',NULL,'Mandative subjunctive: base verb without -s for all persons/numbers.','easy'),
  (cid,55,190,'multiple_choice','[TOEFL Reading] "Were this hypothesis to prove correct, it would require a fundamental revision of the existing model." This means:','If this hypothesis turns out to be correct (which is uncertain), the model would need fundamental revision.','["When this hypothesis proves correct, the model requires revision.","If this hypothesis turns out to be correct (which is uncertain), the model would need fundamental revision.","Because this hypothesis is correct, the model requires fundamental revision.","This hypothesis was correct and the model was revised."]','"Were...to prove" = formal hypothetical, not a factual conditional.','medium'),
  (cid,55,191,'gap_fill','[TOEFL Reading] "It is critical that researchers _____ (disclose) all funding sources and that any potential conflicts of interest _____ (address/passive) in the manuscript." Best mandative forms?','disclose / be addressed',NULL,'"It is critical that" + mandative subjunctive (base verb + passive base verb).','easy'),

  -- BLOCK 56: TOEFL Speaking avançado com subjunctive
  (cid,56,192,'production','[TOEFL Speaking — 45s] A reading outlines proposals for healthcare reform. Use subjunctive in your summary.','',NULL,'The reading puts forward a comprehensive set of recommendations for healthcare reform that center on improving both access and quality. It proposes that universal coverage be established as a legal right, and that no person be denied essential care on the basis of inability to pay. The reading further recommends that primary care capacity be substantially expanded, that community health workers be deployed to underserved populations, and that preventive care receive a significantly higher proportion of public health investment than it currently does. The reading also urges that pharmaceutical pricing be regulated to ensure that essential medicines remain affordable. Were these proposals to be adopted simultaneously, the reading argues, they would produce meaningful improvements in both health outcomes and cost-effectiveness. It is essential, the reading concludes, that policymakers recognize healthcare as a public good rather than a market commodity, and that the governance of health systems be designed accordingly.','hard'),
  (cid,56,193,'production','[TOEFL Speaking — 45s] Use subjunctive to make recommendations about addressing global cybersecurity threats.','',NULL,'Cybersecurity represents one of the most rapidly evolving challenges in international relations, and the evidence suggests that it is essential both that national governments strengthen their defensive capabilities and that international mechanisms for cooperation and norm-setting be developed urgently. It is critical that critical infrastructure — power grids, water systems, financial networks — be protected through mandatory security standards whose implementation be verified by independent auditors. The evidence further suggests that it be mandatory for organizations above a certain size to report significant cyber incidents to national authorities within a defined timeframe, so that threat intelligence can be shared and systemic vulnerabilities identified. Were major powers to agree to a binding norm prohibiting cyberattacks on civilian infrastructure, it would represent a significant step toward reducing the risk of escalation in the digital domain. It is equally important that capacity-building assistance be provided to lower-income countries whose cybersecurity infrastructure is inadequate, since vulnerabilities in any part of the interconnected global system create risks for all participants.','hard'),

  -- BLOCK 57: TOEFL Writing avançado com subjunctive
  (cid,57,194,'production','[TOEFL Writing — 200 words] Write a paragraph on climate finance reform using subjunctive throughout.','',NULL,'The architecture of international climate finance requires fundamental reform if it is to mobilize resources at the scale the challenge demands, and several changes are essential. It is critical that the commitment made by developed countries to provide $100 billion per year in climate finance to developing nations be honored and substantially exceeded rather than repeatedly deferred; that this commitment has not yet been consistently met has significantly undermined trust in the multilateral climate process. It is equally important that the balance between mitigation and adaptation finance be recalibrated: while it is understandable that investors prefer mitigation projects with clearer revenue streams, it is essential that adaptation funding reach the most vulnerable countries whose populations face the most severe climate impacts despite contributing least to the problem. The evidence also suggests that it be mandatory for multilateral development banks to align all new lending with the Paris Agreement''s goals, and that fossil fuel project finance be phased out on a defined timeline. Were a new international facility to be established specifically for climate-related loss and damage — compensating countries for unavoidable impacts — it would address a major political grievance that has complicated climate negotiations. It is imperative that the governance of such a facility be genuinely representative, ensuring that the most affected countries have meaningful decision-making authority.','hard'),
  (cid,57,195,'production','[TOEFL Writing — 200 words] Write a paragraph on academic research integrity using mandative subjunctive for recommendations.','',NULL,'The integrity of the scientific research enterprise depends on the consistent application of a set of standards whose importance is widely acknowledged but whose enforcement remains uneven, and a number of reforms are urgently required. It is essential that institutions require researchers to pre-register their hypotheses and analysis plans before data collection begins, so that post-hoc hypothesis generation — sometimes called HARKing, or hypothesizing after results are known — be reduced substantially. It is also important that journals be mandated to consider pre-registered studies for publication regardless of whether results are statistically significant, addressing the publication bias that distorts the scientific literature. Research funders should insist that all data and materials underlying published findings be made publicly available so that independent replication be facilitated, and that replication studies be treated as a legitimate and fundable research contribution rather than a low-status activity. It is further proposed that institutions be required to establish clear, fair, and transparent procedures for investigating allegations of research misconduct, and that whistleblowers who report genuine misconduct be protected from retaliation. Were these reforms to be adopted systematically across disciplines and institutions, the cumulative effect on the reliability and trustworthiness of the scientific literature would be substantial.','hard'),

  -- BLOCK 58: Final
  (cid,58,196,'production','[TOEFL Writing — 200 words] Write a paragraph on AI ethics and governance using subjunctive throughout.','',NULL,'The governance of artificial intelligence requires urgent attention, and a number of principles and requirements deserve to be established as foundational to any legitimate AI governance framework. It is essential that AI systems deployed in high-stakes domains — criminal justice, healthcare, credit, employment — be subject to mandatory impact assessments before deployment, and that these assessments be conducted by parties independent of the developers. It is equally imperative that individuals who are subject to consequential algorithmic decisions be given meaningful explanations of how those decisions were reached and that they have effective avenues for challenge and appeal. The evidence from jurisdictions that have implemented stronger AI oversight suggests that it be required that AI developers document their training data, model architecture, and evaluation results in standardized formats accessible to regulators. Were a binding international treaty on high-risk AI to be negotiated and ratified by major AI-developing nations, it would create the international governance framework that self-regulatory approaches have so far failed to provide. It is also critical that the governance of AI not be treated as a purely technical domain: the values embedded in AI systems reflect societal choices that require democratic deliberation, and it is essential that affected communities have a genuine role in shaping the frameworks that govern technologies increasingly present in every domain of public and private life.','hard'),
  (cid,58,197,'production','[TOEFL Speaking — 60s] Discuss what reforms international trade organizations need. Use subjunctive throughout.','',NULL,'International trade organizations face a legitimacy crisis that will worsen unless significant reforms are undertaken, and a number of changes are both necessary and feasible. It is essential that the dispute settlement system of the World Trade Organization be reformed so that the Appellate Body, which has been paralyzed by the United States'' refusal to appoint new members, be restored to full functioning. It is also important that the WTO''s negotiating agenda be updated to address the twenty-first century trade issues — digital trade, state-owned enterprises, and subsidies for strategic industries — that the Uruguay Round agreements do not adequately cover. The evidence further suggests that it be mandatory for major trading nations to disclose their industrial policy interventions in a standardized, comparable format, so that the extent of competitive distortion can be assessed transparently. Were the WTO to be reformed to give developing countries more meaningful participation in agenda-setting and decision-making, the institution would better reflect the current distribution of global economic power. It is critical that any reform process be genuinely multilateral rather than driven by the preferences of a small number of large economies, and that the voices of developing nations — whose trade interests have historically received insufficient weight — be heard. It is also imperative that the reformed institution be given more effective tools for addressing currency manipulation and other forms of unfair competition that existing WTO rules do not adequately constrain.','hard'),
  (cid,58,198,'production','[TOEFL Writing — Final 200 words] Write a paragraph on justice system reform using subjunctive for recommendations and conditionals for analysis.','',NULL,'A justice system that fails to deliver outcomes that are both effective and perceived as fair undermines the social contract on which democratic governance depends, and it is essential that reform be approached with both ambition and care. The evidence suggests that it be mandatory for sentencing guidelines to be regularly reviewed for racial and socioeconomic disparities, and that where such disparities are identified, it be required that they be addressed through both prosecutorial training and judicial oversight mechanisms. It is also important that access to legal representation be ensured for all defendants in criminal proceedings and that public defender offices be funded at levels adequate to provide genuinely competent representation. Were restorative justice programs — which bring together offenders, victims, and community members to develop mutually agreed responses to harm — to be scaled significantly, evidence from existing programs suggests that reoffending rates would decline and victim satisfaction with justice processes would improve substantially. It is critical that the purpose of incarceration be clearly defined: evidence strongly suggests that rehabilitation and reintegration goals be prioritized alongside public safety, and that the design of custodial environments reflect these goals rather than defaulting to conditions that undermine them. Only through sustained commitment to evidence-based reform, driven by the requirement that all significant justice policy changes be subject to rigorous evaluation, will meaningful improvement be achievable.','hard')

  ON CONFLICT (content_id, block_number, exercise_number) DO NOTHING;
END $$;
